    /** One accessory by slug, or null when nothing matches. */
    public static function find(string $slug): ?array
    {
        foreach (self::all() as $accessory) {
            if ($accessory['slug'] === $slug) {
                return $accessory;
            }
        }

        return null;
    }

    /** Other accessories of the same type, for the bottom of a product page. */
    public static function related(array $accessory, int $limit = 4): array
    {
        $same = array_values(array_filter(
            self::all(),
            fn ($a) => $a['slug'] !== $accessory['slug']
                && $a['tip'] === $accessory['tip']
                && $a['compatibilitate'] === $accessory['compatibilitate'],
        ));

        return array_slice($same, 0, $limit);
    }
}
